import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

# argwhere returns int64 indices regardless of input dtype
ARGWHERE_DTYPES = utils.FLOAT_DTYPES + utils.INT_DTYPES + [torch.bool]
# Shapes covering 1D through 4D to validate multi-dimensional index decomposition
ARGWHERE_SHAPES = [(4096,), (1024, 1024), (20, 320, 15), (16, 128, 64, 60)]


def make_input(shape, dtype):
    """Random input with zeros scattered so the compaction path is exercised.

    torch.randn never produces exact zeros, so a pure-randn input would keep
    every element non-zero and the compaction logic would go untested.
    """
    if dtype == torch.bool:
        inp = torch.randint(0, 2, shape, dtype=torch.int, device=flag_gems.device).to(
            dtype
        )
    elif dtype in utils.INT_DTYPES:
        inp = torch.randint(-3, 3, shape, device=flag_gems.device).to(dtype)
    else:
        inp = torch.randn(shape, dtype=dtype, device=flag_gems.device)
    flat = inp.view(-1).clone()
    numel = flat.numel()
    if numel > 0:
        flat[::3] = 0  # ~1/3 zeros, spanning multiple blocks
        flat[min(1, numel - 1)] = 0  # zero at the very start
        flat[numel - 1] = 0  # zero at the very end
    return flat.view(shape)


@pytest.mark.argwhere
@pytest.mark.parametrize("shape", ARGWHERE_SHAPES)
@pytest.mark.parametrize("dtype", ARGWHERE_DTYPES)
def test_argwhere(shape, dtype):
    inp = make_input(shape, dtype)
    ref_inp = utils.to_reference(inp, False)

    ref_out = torch.argwhere(ref_inp)
    res_out = flag_gems.argwhere(inp)

    utils.gems_assert_equal(res_out, ref_out)


@pytest.mark.argwhere
@pytest.mark.parametrize(
    "shape",
    [
        (0,),  # empty 1D
        (0, 3),  # empty leading dim
        (5, 0),  # empty trailing dim
        (7,),  # single row, all non-zero after make_input? no: strided zeros
        (1,),  # single element, zeroed below
        (2048, 3),  # zero exactly at a block boundary
        (2, 3, 4, 5, 6),  # 5D
        (2, 2, 2, 2, 2, 2, 2, 2),  # 8D: constexpr fast-path limit
        (2, 2, 2, 2, 2, 2, 2, 2, 2),  # 9D: shape-tensor fallback
    ],
)
def test_argwhere_edge_shapes(shape):
    inp = torch.randn(shape, dtype=torch.float32, device=flag_gems.device)
    flat = inp.view(-1)
    numel = flat.numel()
    if numel > 0:
        flat[::5] = 0
        if numel > 2048:
            flat[2047] = 0  # last element of the first block
            flat[2048] = 0  # first element of the second block
    ref_out = torch.argwhere(utils.to_reference(inp, False))
    res_out = flag_gems.argwhere(inp)

    assert res_out.shape == ref_out.shape
    utils.gems_assert_equal(res_out, ref_out)


@pytest.mark.argwhere
def test_argwhere_special_inputs():
    # all-zero: output is (0, ndim)
    inp = torch.zeros(64, 32, dtype=torch.float32, device=flag_gems.device)
    res_out = flag_gems.argwhere(inp)
    assert res_out.shape == (0, 2)

    # all-non-zero
    inp = torch.ones(64, 32, dtype=torch.float32, device=flag_gems.device)
    ref_out = torch.argwhere(utils.to_reference(inp, False))
    res_out = flag_gems.argwhere(inp)
    utils.gems_assert_equal(res_out, ref_out)

    # NaN / inf are non-zero
    inp = torch.tensor([float("nan"), float("inf"), 0.0, -0.0], device=flag_gems.device)
    ref_out = torch.argwhere(utils.to_reference(inp, False))
    res_out = flag_gems.argwhere(inp)
    utils.gems_assert_equal(res_out, ref_out)

    # non-contiguous input must match the contiguous reference
    inp = torch.randn(8, 8, device=flag_gems.device)[::2, ::3]
    ref_out = torch.argwhere(utils.to_reference(inp, False))
    res_out = flag_gems.argwhere(inp)
    utils.gems_assert_equal(res_out, ref_out)
